.ph-sec{margin-bottom:20px}
.ph-sec:last-child{margin-bottom:0}
.ph-lbl{font-family:var(--mono);font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--acc);display:flex;align-items:center;gap:10px}
