.ph-p b{color:var(--ink);font-weight:500}
.ph-p .g{color:var(--acc);font-weight:500}
.ph-intro{margin-top:9px;color:var(--muted);font-size:12.5px;line-height:1.55;font-weight:300}
/* vertical layer flow */
.vflow{margin-top:16px}
.vrow{display:grid;grid-template-columns:14px 1fr;gap:18px;align-items:center;min-height:33px}
.vmark{position:relative;height:100%;display:flex;align-items:center;justify-content:center}
.vdot{width:8px;height:8px;background:var(--acc);position:relative;z-index:2}
.vrow:not(:last-child) .vmark::after{content:"";position:absolute;top:50%;left:50%;transform:translateX(-50%);width:1px;height:100%;background:var(--line2);z-index:0}
.vbody{display:flex;align-items:baseline;gap:16px}
