#philosophy .sigp::after{bottom:0;right:0;border-bottom-width:2px;border-right-width:2px}
#philosophy .sigp .qx{font-family:'Fraunces',serif;font-style:italic;font-weight:500;font-size:clamp(16px,2.2vw,21px)}
